package agent

import "time"

// AgentSession represents a coding session's data.
// Each agent stores data in its native format (JSONL, SQLite, Markdown, etc.)
// and only the originating agent can read/write it.
//
// Design: Sessions are NOT interoperable between agents. A session created by
// Claude Code can only be read/written by Claude Code. This simplifies the
// implementation as we don't need format conversion.
//
//nolint:revive // AgentSession is clearer than Session in context of the package
type AgentSession struct {
	SessionID  string
	AgentName  AgentName
	RepoPath   string
	SessionRef string // Path/reference to session in agent's storage
	StartTime  time.Time

	// NativeData holds the session content in the agent's native format.
	// Only the originating agent can interpret this data.
	// Examples:
	//   - Claude Code: raw JSONL bytes
	//   - Cursor: serialized SQLite rows
	//   - Aider: Markdown content
	NativeData []byte

	// Computed fields - populated by the agent when reading
	ModifiedFiles []string
	NewFiles      []string
	DeletedFiles  []string

	// Optional normalized entries - agents may populate this if needed
	// for operations that benefit from structured access
	Entries []SessionEntry
}

// SessionEntry represents a single entry in the session
type SessionEntry struct {
	UUID      string
	Type      EntryType
	Timestamp time.Time
	Content   string

	// Tool-specific fields
	ToolName      string
	ToolInput     interface{}
	ToolOutput    interface{}
	FilesAffected []string
}

// EntryType categorizes session entries
type EntryType string

const (
	EntryUser      EntryType = "user"
	EntryAssistant EntryType = "assistant"
	EntryTool      EntryType = "tool"
	EntrySystem    EntryType = "system"
)

// GetLastUserPrompt returns the last user message content
func (s *AgentSession) GetLastUserPrompt() string {
	for i := len(s.Entries) - 1; i >= 0; i-- {
		if s.Entries[i].Type == EntryUser {
			return s.Entries[i].Content
		}
	}
	return ""
}

// GetLastAssistantResponse returns the last assistant message content
func (s *AgentSession) GetLastAssistantResponse() string {
	for i := len(s.Entries) - 1; i >= 0; i-- {
		if s.Entries[i].Type == EntryAssistant {
			return s.Entries[i].Content
		}
	}
	return ""
}

// TruncateAtUUID returns a new session truncated at the given UUID (inclusive)
func (s *AgentSession) TruncateAtUUID(uuid string) *AgentSession {
	if uuid == "" {
		return s
	}

	truncated := &AgentSession{
		SessionID:  s.SessionID,
		AgentName:  s.AgentName,
		RepoPath:   s.RepoPath,
		SessionRef: s.SessionRef,
		StartTime:  s.StartTime,
	}

	for i, entry := range s.Entries {
		truncated.Entries = append(truncated.Entries, entry)
		if entry.UUID == uuid {
			truncated.Entries = s.Entries[:i+1]
			break
		}
	}

	// Recompute file lists from truncated entries
	fileSet := make(map[string]bool)
	for _, entry := range truncated.Entries {
		for _, f := range entry.FilesAffected {
			if !fileSet[f] {
				fileSet[f] = true
				truncated.ModifiedFiles = append(truncated.ModifiedFiles, f)
			}
		}
	}

	return truncated
}

// FindToolResultUUID finds the UUID of the entry containing the tool result
// for the given tool use ID. Returns the UUID and true if found.
func (s *AgentSession) FindToolResultUUID(toolUseID string) (string, bool) {
	for _, entry := range s.Entries {
		if entry.Type == EntryTool && entry.UUID == toolUseID {
			return entry.UUID, true
		}
	}
	return "", false
}

// Package sessionid provides session ID formatting and transformation functions.
// This package has minimal dependencies to avoid import cycles.
package sessionid

import (
	"time"
)

// EntireSessionID generates the full Entire session ID from an agent session UUID.
// The format is: YYYY-MM-DD-<agent-session-uuid>
func EntireSessionID(agentSessionUUID string) string {
	return time.Now().Format("2006-01-02") + "-" + agentSessionUUID
}

// ModelSessionID extracts the agent session UUID from an Entire session ID.
// The Entire session ID format is: YYYY-MM-DD-<agent-session-uuid>
// Returns the original string if it doesn't match the expected format.
func ModelSessionID(entireSessionID string) string {
	// Expected format: YYYY-MM-DD-<agent-uuid> (11 chars prefix: "2026-01-23-")
	if len(entireSessionID) > 11 && entireSessionID[4] == '-' && entireSessionID[7] == '-' && entireSessionID[10] == '-' {
		return entireSessionID[11:]
	}
	// Return as-is if not in expected format (backwards compatibility)
	return entireSessionID
}

package sessionid

import (
	"strings"
	"testing"
	"time"
)

func TestModelSessionID(t *testing.T) {
	tests := []struct {
		name            string
		entireSessionID string
		expectedModelID string
	}{
		// Valid format - extracts UUID
		{
			name:            "valid format with full uuid",
			entireSessionID: "2026-01-23-f736da47-b2ca-4f86-bb32-a1bbe582e464",
			expectedModelID: "f736da47-b2ca-4f86-bb32-a1bbe582e464",
		},
		{
			name:            "valid format with short uuid",
			entireSessionID: "2026-01-23-abc123",
			expectedModelID: "abc123",
		},
		{
			name:            "valid format different year",
			entireSessionID: "2025-12-31-test-session-uuid",
			expectedModelID: "test-session-uuid",
		},
		{
			name:            "valid format single digit day",
			entireSessionID: "2026-01-05-uuid-here",
			expectedModelID: "uuid-here",
		},
		{
			name:            "valid format with complex uuid",
			entireSessionID: "2026-11-30-a1b2c3d4_e5f6_7890",
			expectedModelID: "a1b2c3d4_e5f6_7890",
		},
		// Invalid format - returns as-is (backwards compatibility)
		{
			name:            "no date prefix - plain uuid",
			entireSessionID: "f736da47-b2ca-4f86-bb32-a1bbe582e464",
			expectedModelID: "f736da47-b2ca-4f86-bb32-a1bbe582e464",
		},
		{
			name:            "malformed date - missing second hyphen",
			entireSessionID: "2026-0123-uuid",
			expectedModelID: "2026-0123-uuid",
		},
		{
			name:            "malformed date - missing third hyphen",
			entireSessionID: "2026-01-23uuid",
			expectedModelID: "2026-01-23uuid",
		},
		{
			name:            "too short - only date prefix",
			entireSessionID: "2026-01-23-",
			expectedModelID: "2026-01-23-",
		},
		{
			name:            "too short - less than 11 chars",
			entireSessionID: "2026-01-23",
			expectedModelID: "2026-01-23",
		},
		{
			name:            "empty string",
			entireSessionID: "",
			expectedModelID: "",
		},
		{
			name:            "wrong hyphen positions",
			entireSessionID: "20260-1-23-uuid",
			expectedModelID: "20260-1-23-uuid",
		},
		{
			name:            "date with slashes instead of hyphens",
			entireSessionID: "2026/01/23-uuid",
			expectedModelID: "2026/01/23-uuid",
		},
		{
			name:            "valid format edge case - exactly 11 char prefix",
			entireSessionID: "2026-01-23-x",
			expectedModelID: "x",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := ModelSessionID(tt.entireSessionID)
			if result != tt.expectedModelID {
				t.Errorf("ModelSessionID(%q) = %q, want %q", tt.entireSessionID, result, tt.expectedModelID)
			}
		})
	}
}

func TestEntireSessionID(t *testing.T) {
	tests := []struct {
		name             string
		agentSessionUUID string
	}{
		{name: "full uuid", agentSessionUUID: "f736da47-b2ca-4f86-bb32-a1bbe582e464"},
		{name: "short id", agentSessionUUID: "abc123"},
		{name: "empty uuid", agentSessionUUID: ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := EntireSessionID(tt.agentSessionUUID)

			// Verify format: YYYY-MM-DD-<uuid>
			expectedPrefix := time.Now().Format("2006-01-02") + "-"
			if !strings.HasPrefix(result, expectedPrefix) {
				t.Errorf("EntireSessionID(%q) = %q, expected to start with %q", tt.agentSessionUUID, result, expectedPrefix)
			}

			// Verify UUID is appended correctly
			expectedSuffix := tt.agentSessionUUID
			if !strings.HasSuffix(result, expectedSuffix) {
				t.Errorf("EntireSessionID(%q) = %q, expected to end with %q", tt.agentSessionUUID, result, expectedSuffix)
			}

			// Verify complete format
			expected := expectedPrefix + tt.agentSessionUUID
			if result != expected {
				t.Errorf("EntireSessionID(%q) = %q, want %q", tt.agentSessionUUID, result, expected)
			}
		})
	}
}

// TestRoundTrip verifies that EntireSessionID and ModelSessionID are inverses
func TestRoundTrip(t *testing.T) {
	tests := []struct {
		name string
		uuid string
	}{
		{name: "full uuid", uuid: "f736da47-b2ca-4f86-bb32-a1bbe582e464"},
		{name: "short id", uuid: "abc123"},
		{name: "uuid with underscores", uuid: "test_session_uuid_123"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// UUID -> Entire session ID -> UUID
			entireID := EntireSessionID(tt.uuid)
			extractedUUID := ModelSessionID(entireID)

			if extractedUUID != tt.uuid {
				t.Errorf("Round trip failed: %q -> EntireSessionID -> %q -> ModelSessionID -> %q",
					tt.uuid, entireID, extractedUUID)
			}
		})
	}
}

// Package session provides domain types and interfaces for managing AI coding sessions.
//
// A Session represents a unit of work with an AI agent (Claude Code, Cursor, etc.).
// Sessions can be nested - when a subagent runs, it creates a sub-session within
// the parent session.
//
// This package provides two levels of abstraction:
//
//  1. Sessions interface - High-level CRUD operations for full session objects,
//     combining session state with checkpoint data. This is the primary interface
//     for commands and the UI layer.
//
//  2. StateStore - Low-level primitive for managing session state files in
//     .git/entire-sessions/. This tracks active session state (base commit,
//     checkpoint count, etc.) but doesn't handle checkpoint content. Strategies
//     use this directly for performance-critical state management.
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package session

import (
	"context"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint"
)

// Session represents a unit of work with an AI coding agent.
// Sessions can be nested when subagents are used.
type Session struct {
	// ID is the unique session identifier
	ID string

	// FirstPrompt is the raw first user prompt (immutable)
	FirstPrompt string

	// Description is a human-readable summary (derived or editable)
	Description string

	// StartTime is when the session was started
	StartTime time.Time

	// AgentType identifies the AI agent (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// AgentSessionID is the agent's internal session identifier
	AgentSessionID string

	// Checkpoints contains save points within this session
	Checkpoints []checkpoint.Checkpoint

	// SubSessions contains nested sessions from subagent work
	SubSessions []Session

	// ParentID is the parent session ID (empty for top-level sessions)
	ParentID string

	// ToolUseID is the tool invocation that spawned this sub-session
	// (empty for top-level sessions)
	ToolUseID string
}

// IsSubSession returns true if this session is a sub-session (has a parent).
func (s *Session) IsSubSession() bool {
	return s.ParentID != ""
}

// Sessions provides operations for managing sessions.
type Sessions interface {
	// Create creates a new session with the given options.
	Create(ctx context.Context, opts CreateSessionOptions) (*Session, error)

	// Get retrieves a session by ID.
	Get(ctx context.Context, sessionID string) (*Session, error)

	// List returns all top-level sessions (excludes sub-sessions).
	List(ctx context.Context) ([]Session, error)
}

// CreateSessionOptions contains parameters for creating a new session.
type CreateSessionOptions struct {
	// FirstPrompt is the initial user prompt
	FirstPrompt string

	// AgentType identifies the AI agent (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// AgentSessionID is the agent's internal session identifier
	AgentSessionID string

	// ParentID is the parent session ID for sub-sessions (empty for top-level)
	ParentID string

	// ToolUseID is the tool invocation that spawned this sub-session
	// (empty for top-level sessions)
	ToolUseID string
}

