package session

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/sessionid"
	"entire.io/cli/cmd/entire/cli/validation"
)

const (
	// sessionStateDirName is the directory name for session state files within git common dir.
	sessionStateDirName = "entire-sessions"
)

// State represents the state of an active session.
// This is stored in .git/entire-sessions/<session-id>.json
type State struct {
	// SessionID is the unique session identifier
	SessionID string `json:"session_id"`

	// BaseCommit is the HEAD commit when the session started
	BaseCommit string `json:"base_commit"`

	// WorktreePath is the absolute path to the worktree root
	WorktreePath string `json:"worktree_path,omitempty"`

	// StartedAt is when the session was started
	StartedAt time.Time `json:"started_at"`

	// CheckpointCount is the number of checkpoints created in this session
	CheckpointCount int `json:"checkpoint_count"`

	// CondensedTranscriptLines tracks lines already included in previous condensation
	CondensedTranscriptLines int `json:"condensed_transcript_lines,omitempty"`

	// UntrackedFilesAtStart tracks files that existed at session start (to preserve during rewind)
	UntrackedFilesAtStart []string `json:"untracked_files_at_start,omitempty"`

	// FilesTouched tracks files modified/created/deleted during this session
	FilesTouched []string `json:"files_touched,omitempty"`

	// ConcurrentWarningShown is true if user was warned about concurrent sessions
	ConcurrentWarningShown bool `json:"concurrent_warning_shown,omitempty"`

	// LastCheckpointID is the checkpoint ID from last condensation, reused for subsequent commits without new content
	LastCheckpointID id.CheckpointID `json:"last_checkpoint_id,omitempty"`

	// AgentType identifies the agent that created this session (e.g., "Claude Code", "Gemini CLI", "Cursor")
	AgentType agent.AgentType `json:"agent_type,omitempty"`

	// Token usage tracking (accumulated across all checkpoints in this session)
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

	// Transcript position when session started (for multi-session checkpoints)
	TranscriptLinesAtStart      int    `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

	// TranscriptPath is the path to the live transcript file (for mid-session commit detection)
	TranscriptPath string `json:"transcript_path,omitempty"`

	// PromptAttributions tracks user and agent line changes at each prompt start.
	// This enables accurate attribution by capturing user edits between checkpoints.
	PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

	// PendingPromptAttribution holds attribution calculated at prompt start (before agent runs).
	// This is moved to PromptAttributions when SaveChanges is called.
	PendingPromptAttribution *PromptAttribution `json:"pending_prompt_attribution,omitempty"`
}

// PromptAttribution captures line-level attribution data at the start of each prompt.
// By recording what changed since the last checkpoint BEFORE the agent works,
// we can accurately separate user edits from agent contributions.
type PromptAttribution struct {
	// CheckpointNumber is which checkpoint this was recorded before (1-indexed)
	CheckpointNumber int `json:"checkpoint_number"`

	// UserLinesAdded is lines added by user since the last checkpoint
	UserLinesAdded int `json:"user_lines_added"`

	// UserLinesRemoved is lines removed by user since the last checkpoint
	UserLinesRemoved int `json:"user_lines_removed"`

	// AgentLinesAdded is total agent lines added so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesAdded int `json:"agent_lines_added"`

	// AgentLinesRemoved is total agent lines removed so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesRemoved int `json:"agent_lines_removed"`

	// UserAddedPerFile tracks per-file user additions for accurate modification tracking.
	// This enables distinguishing user self-modifications from agent modifications.
	// See docs/architecture/attribution.md for details.
	UserAddedPerFile map[string]int `json:"user_added_per_file,omitempty"`
}

// StateStore provides low-level operations for managing session state files.
//
// StateStore is a primitive for session state persistence. It is NOT the same as
// the Sessions interface - it only handles state files in .git/entire-sessions/,
// not the full session data which includes checkpoint content.
//
// Use StateStore directly in strategies for performance-critical state operations.
// Use the Sessions interface (when implemented) for high-level session management.
type StateStore struct {
	// stateDir is the directory where session state files are stored
	stateDir string
}

// NewStateStore creates a new state store.
// Uses the git common dir to store session state (shared across worktrees).
func NewStateStore() (*StateStore, error) {
	commonDir, err := getGitCommonDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get git common dir: %w", err)
	}
	return &StateStore{
		stateDir: filepath.Join(commonDir, sessionStateDirName),
	}, nil
}

// NewStateStoreWithDir creates a new state store with a custom directory.
// This is useful for testing.
func NewStateStoreWithDir(stateDir string) *StateStore {
	return &StateStore{stateDir: stateDir}
}

// Load loads the session state for the given session ID.
// Returns (nil, nil) when session file doesn't exist (not an error condition).
func (s *StateStore) Load(ctx context.Context, sessionID string) (*State, error) {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return nil, fmt.Errorf("invalid session ID: %w", err)
	}

	stateFile := s.stateFilePath(sessionID)

	data, err := os.ReadFile(stateFile) //nolint:gosec // stateFile is derived from sessionID
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state: %w", err)
	}

	var state State
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
	}
	return &state, nil
}

// Save saves the session state atomically.
func (s *StateStore) Save(ctx context.Context, state *State) error {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(state.SessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
		return fmt.Errorf("failed to create session state directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal session state: %w", err)
	}

	stateFile := s.stateFilePath(state.SessionID)

	// Atomic write: write to temp file, then rename
	tmpFile := stateFile + ".tmp"
	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
		return fmt.Errorf("failed to write session state: %w", err)
	}
	if err := os.Rename(tmpFile, stateFile); err != nil {
		return fmt.Errorf("failed to rename session state file: %w", err)
	}
	return nil
}

// Clear removes the session state file for the given session ID.
func (s *StateStore) Clear(ctx context.Context, sessionID string) error {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	stateFile := s.stateFilePath(sessionID)

	if err := os.Remove(stateFile); err != nil {
		if os.IsNotExist(err) {
			return nil // Already gone, not an error
		}
		return fmt.Errorf("failed to remove session state file: %w", err)
	}
	return nil
}

// RemoveAll removes the entire session state directory.
// This is used during uninstall to completely remove all session state.
func (s *StateStore) RemoveAll() error {
	if err := os.RemoveAll(s.stateDir); err != nil {
		return fmt.Errorf("failed to remove session state directory: %w", err)
	}
	return nil
}

// List returns all session states.
func (s *StateStore) List(ctx context.Context) ([]*State, error) {
	_ = ctx // Reserved for future use

	entries, err := os.ReadDir(s.stateDir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state directory: %w", err)
	}

	var states []*State
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		if strings.HasSuffix(entry.Name(), ".tmp") {
			continue // Skip temp files
		}

		sessionID := strings.TrimSuffix(entry.Name(), ".json")
		state, err := s.Load(ctx, sessionID)
		if err != nil {
			continue // Skip corrupted state files
		}
		if state == nil {
			continue
		}

		states = append(states, state)
	}
	return states, nil
}

// FindByBaseCommit finds all sessions based on the given commit hash.
func (s *StateStore) FindByBaseCommit(ctx context.Context, baseCommit string) ([]*State, error) {
	allStates, err := s.List(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*State
	for _, state := range allStates {
		if state.BaseCommit == baseCommit {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// FindByWorktree finds all sessions for the given worktree path.
func (s *StateStore) FindByWorktree(ctx context.Context, worktreePath string) ([]*State, error) {
	allStates, err := s.List(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*State
	for _, state := range allStates {
		if state.WorktreePath == worktreePath {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// stateFilePath returns the path to a session state file.
func (s *StateStore) stateFilePath(sessionID string) string {
	return filepath.Join(s.stateDir, sessionID+".json")
}

// getGitCommonDir returns the path to the shared git directory.
// In a regular checkout, this is .git/
// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
func getGitCommonDir() (string, error) {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = "."
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))

	// git rev-parse --git-common-dir returns relative paths from the working directory,
	// so we need to make it absolute if it isn't already
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(".", commonDir)
	}

	return filepath.Clean(commonDir), nil
}

// GetWorktreePath returns the absolute path to the current worktree root.
func GetWorktreePath() (string, error) {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get worktree path: %w", err)
	}
	return strings.TrimSpace(string(output)), nil
}

// GetOrCreateEntireSessionID returns a stable session ID for the given agent session ID.
// If a session state already exists with this ID, returns that session ID
// (preserving the original date prefix). Otherwise creates a new ID with today's date.
//
// When multiple state files exist for the same ID (due to the midnight-crossing bug),
// this function picks the most recent by date and cleans up older duplicates.
//
// This function never returns an error - it always falls back to generating a new ID
// if any issues occur (e.g., corrupt git repo, permission problems, invalid ID).
//
// Note: This function is not thread-safe. Concurrent calls with the same ID may
// race on file cleanup. In practice this is not an issue since agent hooks are
// called sequentially within a session.
func GetOrCreateEntireSessionID(agentSessionID string) string {
	// Validate ID format to prevent path traversal attacks
	if err := validation.ValidateAgentSessionID(agentSessionID); err != nil {
		logging.Warn(context.Background(), "invalid agent session ID",
			slog.String("input", agentSessionID),
			slog.Any("error", err))
		// Invalid ID - return it anyway (will fail downstream with clearer error)
		// Don't generate random ID as that breaks session continuity
		return sessionid.EntireSessionID(agentSessionID)
	}

	commonDir, err := getGitCommonDir()
	if err != nil {
		// Can't get common dir (corrupt git repo?) - fall back to new ID
		return sessionid.EntireSessionID(agentSessionID)
	}

	stateDir := filepath.Join(commonDir, sessionStateDirName)
	entries, err := os.ReadDir(stateDir)
	if err != nil {
		// State dir doesn't exist or can't read it - fall back to new ID
		return sessionid.EntireSessionID(agentSessionID)
	}

	// Collect all matching session IDs
	var matches []string
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}

		existingSessionID := strings.TrimSuffix(entry.Name(), ".json")
		existingUUID := sessionid.ModelSessionID(existingSessionID)

		if existingUUID == agentSessionID {
			matches = append(matches, existingSessionID)
		}
	}

	if len(matches) == 0 {
		// No existing session found - create new ID with today's date
		return sessionid.EntireSessionID(agentSessionID)
	}

	// Pick most recent (YYYY-MM-DD sorts correctly lexicographically)
	sort.Strings(matches)
	mostRecent := matches[len(matches)-1]

	// Best-effort cleanup of old duplicates (ignore errors)
	for _, oldID := range matches[:len(matches)-1] {
		oldFile := filepath.Join(stateDir, oldID+".json")
		_ = os.Remove(oldFile)
	}

	return mostRecent
}

// hooks_claudecode_handlers.go contains Claude Code specific hook handler implementations.
// These are called by the hook registry in hook_registry.go.
package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/agent/claudecode"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/session"
	"entire.io/cli/cmd/entire/cli/sessionid"
	"entire.io/cli/cmd/entire/cli/strategy"
	"entire.io/cli/cmd/entire/cli/validation"
)

// currentSessionIDWithFallback returns the persisted Entire session ID when available.
// Falls back to deriving from the model session ID for backward compatibility.
func currentSessionIDWithFallback(modelSessionID string) string {
	entireSessionID, err := paths.ReadCurrentSession()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to read current session: %v\n", err)
	}
	if entireSessionID != "" {
		// Validate persisted session ID to fail-fast on corrupted files
		if err := validation.ValidateSessionID(entireSessionID); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: invalid persisted session ID: %v\n", err)
			// Fall through to fallback
		} else if modelSessionID == "" || sessionid.ModelSessionID(entireSessionID) == modelSessionID {
			return entireSessionID
		} else {
			fmt.Fprintf(os.Stderr, "Warning: persisted session ID does not match hook session ID\n")
		}
	}
	if modelSessionID == "" {
		return ""
	}
	// Get or create stable session ID (reuses existing if session resumed across days)
	return session.GetOrCreateEntireSessionID(modelSessionID)
}

// hookInputData contains parsed hook input and session identifiers.
type hookInputData struct {
	agent           agent.Agent
	input           *agent.HookInput
	modelSessionID  string
	entireSessionID string
}

// parseAndLogHookInput parses the hook input and sets up logging context.
func parseAndLogHookInput() (*hookInputData, error) {
	// Get the agent from the hook command context (e.g., "entire hooks claude-code ...")
	ag, err := GetCurrentHookAgent()
	if err != nil {
		return nil, fmt.Errorf("failed to get agent: %w", err)
	}

	// Parse hook input using agent interface
	input, err := ag.ParseHookInput(agent.HookUserPromptSubmit, os.Stdin)
	if err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}

	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
	logging.Info(logCtx, "user-prompt-submit",
		slog.String("hook", "user-prompt-submit"),
		slog.String("hook_type", "agent"),
		slog.String("model_session_id", input.SessionID),
		slog.String("transcript_path", input.SessionRef),
	)

	modelSessionID := input.SessionID
	if modelSessionID == "" {
		modelSessionID = unknownSessionID
	}

	// Get the Entire session ID, preferring the persisted value to handle midnight boundary
	entireSessionID := currentSessionIDWithFallback(modelSessionID)

	return &hookInputData{
		agent:           ag,
		input:           input,
		modelSessionID:  modelSessionID,
		entireSessionID: entireSessionID,
	}, nil
}

// checkConcurrentSessions checks for concurrent session conflicts and shows warnings if needed.
// Returns true if the hook should be skipped due to an unresolved conflict.
func checkConcurrentSessions(ag agent.Agent, entireSessionID string) (bool, error) {
	// Check if warnings are disabled via settings
	if IsMultiSessionWarningDisabled() {
		return false, nil
	}

	strat := GetStrategy()

	concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker)
	if !ok {
		return false, nil // Strategy doesn't support concurrent checks
	}

	// Check if this session already acknowledged the warning
	existingState, loadErr := strategy.LoadSessionState(entireSessionID)
	warningAlreadyShown := loadErr == nil && existingState != nil && existingState.ConcurrentWarningShown

	// Check for other active sessions with checkpoints (on current HEAD)
	otherSession, checkErr := concurrentChecker.HasOtherActiveSessionsWithCheckpoints(entireSessionID)
	hasConflict := checkErr == nil && otherSession != nil

	if warningAlreadyShown {
		if hasConflict {
			// Warning was shown and conflict still exists - skip hooks
			return true, nil
		}
		// Warning was shown but conflict is resolved (e.g., user committed)
		// Clear the flag and proceed normally
		if existingState != nil {
			existingState.ConcurrentWarningShown = false
			if saveErr := strategy.SaveSessionState(existingState); saveErr != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to clear concurrent warning flag: %v\n", saveErr)
			}
		}
		return false, nil
	}

	if hasConflict {
		// First time seeing conflict - show warning
		// Include BaseCommit and WorktreePath so session state is complete for condensation
		repo, err := strategy.OpenRepository()
		if err != nil {
			// Output user-friendly error message via hook response
			if outputErr := outputHookResponse(false, fmt.Sprintf("Failed to open git repository: %v\n\nPlease ensure you're in a git repository and try again.", err)); outputErr != nil {
				return false, outputErr
			}
			return true, nil // Skip hook after outputting response
		}
		head, err := repo.Head()
		if err != nil {
			// Output user-friendly error message via hook response
			if outputErr := outputHookResponse(false, fmt.Sprintf("Failed to get git HEAD: %v\n\nPlease ensure the repository has at least one commit.", err)); outputErr != nil {
				return false, outputErr
			}
			return true, nil // Skip hook after outputting response
		}
		worktreePath, err := strategy.GetWorktreePath()
		if err != nil {
			// Non-fatal: continue without worktree path
			worktreePath = ""
		}
		agentType := ag.Type()
		newState := &strategy.SessionState{
			SessionID:              entireSessionID,
			BaseCommit:             head.Hash().String(),
			WorktreePath:           worktreePath,
			ConcurrentWarningShown: true,
			StartedAt:              time.Now(),
			AgentType:              agentType,
		}
		if saveErr := strategy.SaveSessionState(newState); saveErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to save session state: %v\n", saveErr)
		}

		// Get resume command for the other session using the CONFLICTING session's agent type.
		// If the conflicting session is from a different agent (e.g., Gemini when we're Claude),
		// use that agent's resume command format. Otherwise, use our own format (backward compatible).
		var resumeCmd string
		if otherSession.AgentType != "" && otherSession.AgentType != agentType {
			// Different agent type - look up the conflicting agent
			if conflictingAgent, agentErr := agent.GetByAgentType(otherSession.AgentType); agentErr == nil {
				resumeCmd = conflictingAgent.FormatResumeCommand(conflictingAgent.ExtractAgentSessionID(otherSession.SessionID))
			}
		}
		// Fall back to current agent if same type or couldn't get the conflicting agent
		if resumeCmd == "" {
			resumeCmd = ag.FormatResumeCommand(ag.ExtractAgentSessionID(otherSession.SessionID))
		}

		// Try to read the other session's initial prompt
		otherPrompt := strategy.ReadSessionPromptFromShadow(repo, otherSession.BaseCommit, otherSession.SessionID)

		// Build message with other session's prompt if available
		var message string
		suppressHint := "\n\nTo suppress this warning in future sessions, run:\n  entire enable --disable-multisession-warning"
		if otherPrompt != "" {
			message = fmt.Sprintf("Another session is active: \"%s\"\n\nYou can continue here, but checkpoints from both sessions will be interleaved.\n\nTo resume the other session instead, exit Claude and run: %s%s\n\nPress the up arrow key to get your prompt back.", otherPrompt, resumeCmd, suppressHint)
		} else {
			message = "Another session is active with uncommitted changes. You can continue here, but checkpoints from both sessions will be interleaved.\n\nTo resume the other session instead, exit Claude and run: " + resumeCmd + suppressHint + "\n\nPress the up arrow key to get your prompt back."
		}

		// Output blocking JSON response - warn about concurrent sessions but allow continuation
		// Both sessions will capture checkpoints, which will be interleaved on the shadow branch
		if err := outputHookResponse(false, message); err != nil {
			return false, err // Failed to output response
		}
		// Block the first prompt to show the warning, but subsequent prompts will proceed
		return true, nil
	}

	return false, nil
}

// handleSessionInitErrors handles session initialization errors and provides user-friendly messages.
func handleSessionInitErrors(ag agent.Agent, initErr error) error {
	// Check for shadow branch conflict error (worktree conflict)
	var conflictErr *strategy.ShadowBranchConflictError
	if errors.As(initErr, &conflictErr) {
		message := fmt.Sprintf(
			"Warning: Shadow branch conflict detected!\n\n"+
				"Branch: %s\n"+
				"Existing session: %s\n"+
				"From worktree: %s\n"+
				"Started: %s\n\n"+
				"This may indicate another agent session is active from a different worktree,\n"+
				"or a previous session wasn't completed.\n\n"+
				"Options:\n"+
				"1. Commit your changes (git commit) to create a new base commit\n"+
				"2. Run 'entire rewind reset' to discard the shadow branch and start fresh\n"+
				"3. Continue the previous session from the original worktree: %s",
			conflictErr.Branch,
			conflictErr.ExistingSession,
			conflictErr.ExistingWorktree,
			conflictErr.LastActivity.Format(time.RFC822),
			conflictErr.ExistingWorktree,
		)
		// Output blocking JSON response - user must resolve conflict before continuing
		if err := outputHookResponse(false, message); err != nil {
			return err
		}
		// Return nil so hook exits cleanly (status 0), not with error status
		return nil
	}

	// Check for session ID conflict error (shadow branch has different session)
	var sessionConflictErr *strategy.SessionIDConflictError
	if errors.As(initErr, &sessionConflictErr) {
		// If multi-session warnings are disabled, skip this error silently
		// The user has explicitly opted to work with multiple concurrent sessions
		if IsMultiSessionWarningDisabled() {
			return nil
		}

		// Check if EITHER session has the concurrent warning shown
		// If so, the user was already warned and chose to continue - allow concurrent sessions
		existingState, loadErr := strategy.LoadSessionState(sessionConflictErr.ExistingSession)
		newState, newLoadErr := strategy.LoadSessionState(sessionConflictErr.NewSession)
		if (loadErr == nil && existingState != nil && existingState.ConcurrentWarningShown) ||
			(newLoadErr == nil && newState != nil && newState.ConcurrentWarningShown) {
			// At least one session was warned - allow concurrent operation
			return nil
		}
		// Try to get the conflicting session's agent type from its state file
		// If it's a different agent type, use that agent's resume command format
		var resumeCmd string
		if loadErr == nil && existingState != nil && existingState.AgentType != "" {
			if conflictingAgent, agentErr := agent.GetByAgentType(existingState.AgentType); agentErr == nil {
				resumeCmd = conflictingAgent.FormatResumeCommand(conflictingAgent.ExtractAgentSessionID(sessionConflictErr.ExistingSession))
			}
		}
		// Fall back to current agent if we couldn't get the conflicting agent
		if resumeCmd == "" {
			resumeCmd = ag.FormatResumeCommand(ag.ExtractAgentSessionID(sessionConflictErr.ExistingSession))
		}
		message := fmt.Sprintf(
			"Warning: Session ID conflict detected!\n\n"+
				"Shadow branch: %s\n"+
				"Existing session: %s\n"+
				"New session: %s\n\n"+
				"The shadow branch already has checkpoints from a different session.\n"+
				"Starting a new session would orphan the existing work.\n\n"+
				"Options:\n"+
				"1. Commit your changes (git commit) to create a new base commit\n"+
				"2. Run 'entire rewind reset' to discard the shadow branch and start fresh\n"+
				"3. Resume the existing session: %s\n\n"+
				"To suppress this warning in future sessions, run:\n"+
				"  entire enable --disable-multisession-warning",
			sessionConflictErr.ShadowBranch,
			sessionConflictErr.ExistingSession,
			sessionConflictErr.NewSession,
			resumeCmd,
		)
		// Output blocking JSON response - user must resolve conflict before continuing
		if err := outputHookResponse(false, message); err != nil {
			return err
		}
		// Return nil so hook exits cleanly (status 0), not with error status
		return nil
	}

	// Unknown error type
	fmt.Fprintf(os.Stderr, "Warning: failed to initialize session state: %v\n", initErr)
	return nil
}

// captureInitialState captures the initial state on user prompt submit.
func captureInitialState() error {
	// Parse hook input and setup logging
	hookData, err := parseAndLogHookInput()
	if err != nil {
		return err
	}

	// UNLESS the situation has changed (e.g., user committed, so no more conflict).
	skipHook, err := checkConcurrentSessions(hookData.agent, hookData.entireSessionID)
	if err != nil {
		return err
	}
	if skipHook {
		return nil
	}

	// CLI captures state directly (including transcript position)
	if err := CapturePrePromptState(hookData.entireSessionID, hookData.input.SessionRef); err != nil {
		return err
	}

	// If strategy implements SessionInitializer, call it to initialize session state
	strat := GetStrategy()
	if initializer, ok := strat.(strategy.SessionInitializer); ok {
		agentType := hookData.agent.Type()
		if initErr := initializer.InitializeSession(hookData.entireSessionID, agentType, hookData.input.SessionRef); initErr != nil {
			if err := handleSessionInitErrors(hookData.agent, initErr); err != nil {
				return err
			}
		}
	}

	return nil
}

// commitWithMetadata commits the session changes with metadata.
func commitWithMetadata() error {
	// Skip on default branch for strategies that don't allow it
	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
		return nil // Don't fail the hook, just skip
	}

	// Get the agent for hook input parsing and session ID transformation
	ag, err := GetCurrentHookAgent()
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Parse hook input using agent interface
	input, err := ag.ParseHookInput(agent.HookStop, os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to parse hook input: %w", err)
	}

	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
	logging.Info(logCtx, "stop",
		slog.String("hook", "stop"),
		slog.String("hook_type", "agent"),
		slog.String("model_session_id", input.SessionID),
		slog.String("transcript_path", input.SessionRef),
	)

	modelSessionID := input.SessionID
	if modelSessionID == "" {
		modelSessionID = unknownSessionID
	}

	// Get the Entire session ID, preferring the persisted value to handle midnight boundary
	entireSessionID := currentSessionIDWithFallback(modelSessionID)

	transcriptPath := input.SessionRef
	if transcriptPath == "" || !fileExists(transcriptPath) {
		return fmt.Errorf("transcript file not found or empty: %s", transcriptPath)
	}

	// Create session metadata folder using the entire session ID (preserves original date on resume)
	// Use AbsPath to ensure we create at repo root, not relative to cwd
	sessionDir := paths.SessionMetadataDirFromEntireID(entireSessionID)
	sessionDirAbs, err := paths.AbsPath(sessionDir)
	if err != nil {
		sessionDirAbs = sessionDir // Fallback to relative
	}
	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// Copy transcript
	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
	if err := copyFile(transcriptPath, logFile); err != nil {
		return fmt.Errorf("failed to copy transcript: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Copied transcript to: %s\n", sessionDir+"/"+paths.TranscriptFileName)

	// Load session state to get transcript offset (for strategies that track it)
	// This is used to only parse NEW transcript lines since the last checkpoint
	var transcriptOffset int
	sessionState, loadErr := strategy.LoadSessionState(entireSessionID)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state: %v\n", loadErr)
	}
	if sessionState != nil {
		transcriptOffset = sessionState.CondensedTranscriptLines
		fmt.Fprintf(os.Stderr, "Session state found: parsing transcript from line %d\n", transcriptOffset)
	}

	// Parse transcript (optionally from offset for strategies that track transcript position)
	// When transcriptOffset > 0, only parse NEW lines since the last checkpoint
	var transcript []transcriptLine
	var totalLines int
	if transcriptOffset > 0 {
		// Parse only NEW lines since last checkpoint
		transcript, totalLines, err = parseTranscriptFromLine(transcriptPath, transcriptOffset)
		if err != nil {
			return fmt.Errorf("failed to parse transcript from line %d: %w", transcriptOffset, err)
		}
		fmt.Fprintf(os.Stderr, "Parsed %d new transcript lines (total: %d)\n", len(transcript), totalLines)
	} else {
		// First prompt or no session state - parse entire transcript
		// Use parseTranscriptFromLine with offset 0 to also get totalLines
		transcript, totalLines, err = parseTranscriptFromLine(transcriptPath, 0)
		if err != nil {
			return fmt.Errorf("failed to parse transcript: %w", err)
		}
	}

	// Extract all prompts since last checkpoint for prompt file
	allPrompts := extractUserPrompts(transcript)
	promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
	promptContent := strings.Join(allPrompts, "\n\n---\n\n")
	if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
		return fmt.Errorf("failed to write prompt file: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)

	// Extract summary
	summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
	summary := extractLastAssistantMessage(transcript)
	if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
		return fmt.Errorf("failed to write summary file: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)

	// Get modified files from transcript
	modifiedFiles := extractModifiedFiles(transcript)

	// Generate commit message from last user prompt
	lastPrompt := ""
	if len(allPrompts) > 0 {
		lastPrompt = allPrompts[len(allPrompts)-1]
	}
	commitMessage := generateCommitMessage(lastPrompt)
	fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)

	// Get repo root for path conversion (not cwd, since Claude may be in a subdirectory)
	// Using cwd would filter out files in sibling directories (paths starting with ..)
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repo root: %w", err)
	}

	// Load pre-prompt state (captured on UserPromptSubmit)
	preState, err := LoadPrePromptState(entireSessionID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
	}
	if preState != nil {
		fmt.Fprintf(os.Stderr, "Loaded pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
	}

	// Compute new files (files created during session)
	newFiles, err := ComputeNewFiles(preState)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to compute new files: %v\n", err)
	}

	// Compute deleted files (tracked files that were deleted)
	deletedFiles, err := ComputeDeletedFiles()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to compute deleted files: %v\n", err)
	}

	// Filter and normalize all paths (CLI responsibility)
	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	relNewFiles := FilterAndNormalizePaths(newFiles, repoRoot)
	relDeletedFiles := FilterAndNormalizePaths(deletedFiles, repoRoot)

	// Check if there are any changes to commit
	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
	if totalChanges == 0 {
		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
		fmt.Fprintf(os.Stderr, "Skipping commit\n")
		// Clean up state even when skipping
		if err := CleanupPrePromptState(entireSessionID); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", err)
		}
		return nil
	}

	fmt.Fprintf(os.Stderr, "Files modified during session (%d):\n", len(relModifiedFiles))
	for _, file := range relModifiedFiles {
		fmt.Fprintf(os.Stderr, "  - %s\n", file)
	}
	if len(relNewFiles) > 0 {
		fmt.Fprintf(os.Stderr, "New files created (%d):\n", len(relNewFiles))
		for _, file := range relNewFiles {
			fmt.Fprintf(os.Stderr, "  + %s\n", file)
		}
	}
	if len(relDeletedFiles) > 0 {
		fmt.Fprintf(os.Stderr, "Files deleted (%d):\n", len(relDeletedFiles))
		for _, file := range relDeletedFiles {
			fmt.Fprintf(os.Stderr, "  - %s\n", file)
		}
	}

	// Create context file before saving changes
	contextFile := filepath.Join(sessionDirAbs, paths.ContextFileName)
	if err := createContextFileMinimal(contextFile, commitMessage, entireSessionID, promptFile, summaryFile, transcript); err != nil {
		return fmt.Errorf("failed to create context file: %w", err)
	}
	fmt.Fprintf(os.Stderr, "Created context file: %s\n", sessionDir+"/"+paths.ContextFileName)

	// Get git author from local/global config
	author, err := GetGitAuthor()
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Get the configured strategy
	strat := GetStrategy()

	// Ensure strategy setup is in place (auto-installs git hook, gitignore, etc. if needed)
	if err := strat.EnsureSetup(); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
	}

	// Get agent type from the currently executing hook agent (authoritative source)
	var agentType agent.AgentType
	if hookAgent, agentErr := GetCurrentHookAgent(); agentErr == nil {
		agentType = hookAgent.Type()
	}

	// Get transcript position from pre-prompt state (captured at checkpoint start)
	var transcriptIdentifierAtStart string
	var transcriptLinesAtStart int
	if preState != nil {
		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
		transcriptLinesAtStart = preState.LastTranscriptLineCount
	}

	// Calculate token usage for this checkpoint (Claude Code specific)
	var tokenUsage *agent.TokenUsage
	if transcriptPath != "" {
		// Subagents are stored in a subagents/ directory next to the main transcript
		subagentsDir := filepath.Join(filepath.Dir(transcriptPath), entireSessionID, "subagents")
		usage, err := claudecode.CalculateTotalTokenUsage(transcriptPath, transcriptLinesAtStart, subagentsDir)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", err)
		} else {
			tokenUsage = usage
		}
	}

	// Build fully-populated save context and delegate to strategy
	ctx := strategy.SaveContext{
		SessionID:                   entireSessionID,
		ModifiedFiles:               relModifiedFiles,
		NewFiles:                    relNewFiles,
		DeletedFiles:                relDeletedFiles,
		MetadataDir:                 sessionDir,
		MetadataDirAbs:              sessionDirAbs,
		CommitMessage:               commitMessage,
		TranscriptPath:              transcriptPath,
		AuthorName:                  author.Name,
		AuthorEmail:                 author.Email,
		AgentType:                   agentType,
		TranscriptIdentifierAtStart: transcriptIdentifierAtStart,
		TranscriptLinesAtStart:      transcriptLinesAtStart,
		TokenUsage:                  tokenUsage,
	}

	if err := strat.SaveChanges(ctx); err != nil {
		return fmt.Errorf("failed to save changes: %w", err)
	}

	// Update session state with new transcript position for strategies that create
	// commits on the active branch (auto-commit strategy). This prevents parsing old transcript
	// lines on subsequent checkpoints.
	// Note: Shadow strategy doesn't create commits on the active branch, so its
	// checkpoints don't "consume" the transcript in the same way. Shadow should
	// continue parsing the full transcript to capture all files touched in the session.
	if strat.Name() == strategy.StrategyNameAutoCommit {
		// Create session state lazily if it doesn't exist (backward compat for resumed sessions
		// or if InitializeSession was never called/failed)
		if sessionState == nil {
			sessionState = &strategy.SessionState{
				SessionID: entireSessionID,
			}
		}
		sessionState.CondensedTranscriptLines = totalLines
		sessionState.CheckpointCount++
		if updateErr := strategy.SaveSessionState(sessionState); updateErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to update session state: %v\n", updateErr)
		} else {
			fmt.Fprintf(os.Stderr, "Updated session state: transcript position=%d, checkpoint=%d\n",
				totalLines, sessionState.CheckpointCount)
		}
	}

	// Clean up pre-prompt state (CLI responsibility)
	if err := CleanupPrePromptState(entireSessionID); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", err)
	}

	return nil
}

// handlePostTodo handles the PostToolUse[TodoWrite] hook for subagent checkpoints.
// Creates a checkpoint if we're in a subagent context (active pre-task file exists).
// Skips silently if not in subagent context (main agent).
func handlePostTodo() error {
	input, err := parseSubagentCheckpointHookInput(os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to parse PostToolUse[TodoWrite] input: %w", err)
	}

	// Get agent for logging context
	ag, err := GetCurrentHookAgent()
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
	logging.Info(logCtx, "post-todo",
		slog.String("hook", "post-todo"),
		slog.String("hook_type", "subagent"),
		slog.String("model_session_id", input.SessionID),
		slog.String("transcript_path", input.TranscriptPath),
		slog.String("tool_use_id", input.ToolUseID),
	)

	// Check if we're in a subagent context by looking for an active pre-task file
	taskToolUseID, found := FindActivePreTaskFile()
	if !found {
		// Not in subagent context - this is a main agent TodoWrite, skip
		return nil
	}

	// Skip on default branch to avoid polluting main/master history
	if skip, branchName := ShouldSkipOnDefaultBranch(); skip {
		fmt.Fprintf(os.Stderr, "Entire: skipping incremental checkpoint on branch '%s'\n", branchName)
		return nil
	}

	// Detect file changes since last checkpoint
	modified, newFiles, deleted, err := DetectChangedFiles()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to detect changed files: %v\n", err)
		return nil
	}

	// If no file changes, skip creating a checkpoint
	if len(modified) == 0 && len(newFiles) == 0 && len(deleted) == 0 {
		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping incremental checkpoint\n")
		return nil
	}

	// Get git author
	author, err := GetGitAuthor()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to get git author: %v\n", err)
		return nil
	}

	// Get the active strategy
	strat := GetStrategy()

	// Ensure strategy setup is complete
	if err := strat.EnsureSetup(); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
		return nil
	}

	// Get the session ID from the transcript path or input, then transform to Entire session ID
	sessionID := paths.ExtractSessionIDFromTranscriptPath(input.TranscriptPath)
	if sessionID == "" {
		sessionID = input.SessionID
	}
	entireSessionID := currentSessionIDWithFallback(sessionID)

	// Get next checkpoint sequence
	seq := GetNextCheckpointSequence(entireSessionID, taskToolUseID)

	// Extract the todo content from the tool_input.
	// PostToolUse receives the NEW todo list where the just-completed work is
	// marked as "completed". The last completed item is the work that was just done.
	todoContent := ExtractLastCompletedTodoFromToolInput(input.ToolInput)
	if todoContent == "" {
		// No completed items - this is likely the first TodoWrite (planning phase).
		// Check if there are any todos at all to avoid duplicate messages.
		todoCount := CountTodosFromToolInput(input.ToolInput)
		if todoCount > 0 {
			// Use "Planning: N todos" format for the first TodoWrite
			todoContent = fmt.Sprintf("Planning: %d todos", todoCount)
		}
		// If todoCount == 0, todoContent remains empty and FormatIncrementalMessage
		// will fall back to "Checkpoint #N" format
	}

	// Get agent type from the currently executing hook agent (authoritative source)
	var agentType agent.AgentType
	if hookAgent, agentErr := GetCurrentHookAgent(); agentErr == nil {
		agentType = hookAgent.Type()
	}

	// Build incremental checkpoint context
	ctx := strategy.TaskCheckpointContext{
		SessionID:           entireSessionID,
		ToolUseID:           taskToolUseID,
		ModifiedFiles:       modified,
		NewFiles:            newFiles,
		DeletedFiles:        deleted,
		TranscriptPath:      input.TranscriptPath,
		AuthorName:          author.Name,
		AuthorEmail:         author.Email,
		IsIncremental:       true,
		IncrementalSequence: seq,
		IncrementalType:     input.ToolName,
		IncrementalData:     input.ToolInput,
		TodoContent:         todoContent,
		AgentType:           agentType,
	}

	// Save incremental checkpoint
	if err := strat.SaveTaskCheckpoint(ctx); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to save incremental checkpoint: %v\n", err)
		return nil
	}

	fmt.Fprintf(os.Stderr, "[entire] Created incremental checkpoint #%d for %s (task: %s)\n",
		seq, input.ToolName, taskToolUseID[:min(12, len(taskToolUseID))])
	return nil
}

// handlePreTask handles the PreToolUse[Task] hook
func handlePreTask() error {
	// Skip on default branch for strategies that don't allow it
	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
		return nil // Don't fail the hook, just skip
	}

	input, err := parseTaskHookInput(os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to parse PreToolUse[Task] input: %w", err)
	}

	// Get agent for logging context
	ag, err := GetCurrentHookAgent()
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
	logging.Info(logCtx, "pre-task",
		slog.String("hook", "pre-task"),
		slog.String("hook_type", "subagent"),
		slog.String("model_session_id", input.SessionID),
		slog.String("transcript_path", input.TranscriptPath),
		slog.String("tool_use_id", input.ToolUseID),
	)

	// Log context to stdout
	logPreTaskHookContext(os.Stdout, input)

	// Capture pre-task state locally (for computing new files when task completes).
	// We don't create a shadow branch commit here. Commits are created during
	// task completion (handlePostTask/handlePostTodo) only if the task resulted
	// in file changes.
	if err := CapturePreTaskState(input.ToolUseID); err != nil {
		return fmt.Errorf("failed to capture pre-task state: %w", err)
	}

	return nil
}

// handlePostTask handles the PostToolUse[Task] hook
func handlePostTask() error {
	// Skip on default branch for strategies that don't allow it
	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
		return nil // Don't fail the hook, just skip
	}

	input, err := parsePostTaskHookInput(os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to parse PostToolUse[Task] input: %w", err)
	}

	// Extract subagent type from tool_input for logging
	subagentType, taskDescription := ParseSubagentTypeAndDescription(input.ToolInput)

	// Get agent for logging context
	ag, err := GetCurrentHookAgent()
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Log parsed input context
	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
	logging.Info(logCtx, "post-task",
		slog.String("hook", "post-task"),
		slog.String("hook_type", "subagent"),
		slog.String("tool_use_id", input.ToolUseID),
		slog.String("agent_id", input.AgentID),
		slog.String("subagent_type", subagentType),
	)

	// Determine subagent transcript path
	transcriptDir := filepath.Dir(input.TranscriptPath)
	var subagentTranscriptPath string
	if input.AgentID != "" {
		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, input.AgentID)
		if !fileExists(subagentTranscriptPath) {
			subagentTranscriptPath = ""
		}
	}

	// Log context to stdout
	logPostTaskHookContext(os.Stdout, input, subagentTranscriptPath)

	// Parse transcript to extract modified files
	var modifiedFiles []string
	if subagentTranscriptPath != "" {
		// Use subagent transcript if available
		transcript, err := parseTranscript(subagentTranscriptPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to parse subagent transcript: %v\n", err)
		} else {
			modifiedFiles = extractModifiedFiles(transcript)
		}
	} else {
		// Fall back to main transcript
		transcript, err := parseTranscript(input.TranscriptPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to parse transcript: %v\n", err)
		} else {
			modifiedFiles = extractModifiedFiles(transcript)
		}
	}

	// Load pre-task state and compute new files
	preState, err := LoadPreTaskState(input.ToolUseID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-task state: %v\n", err)
	}
	newFiles, err := ComputeNewFilesFromTask(preState)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to compute new files: %v\n", err)
	}

	// Get repo root for path conversion (not cwd, since Claude may be in a subdirectory)
	// Using cwd would filter out files in sibling directories (paths starting with ..)
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repo root: %w", err)
	}

	// Filter and normalize paths
	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	relNewFiles := FilterAndNormalizePaths(newFiles, repoRoot)

	// If no file changes, skip creating a checkpoint
	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 {
		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping task checkpoint\n")
		// Cleanup pre-task state (ignore error - cleanup is best-effort)
		_ = CleanupPreTaskState(input.ToolUseID) //nolint:errcheck // best-effort cleanup
		return nil
	}

	// Find checkpoint UUID from main transcript (best-effort, ignore errors)
	transcript, _ := parseTranscript(input.TranscriptPath) //nolint:errcheck // best-effort extraction
	checkpointUUID, _ := FindCheckpointUUID(transcript, input.ToolUseID)

	// Get git author
	author, err := GetGitAuthor()
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Get the configured strategy
	strat := GetStrategy()

	// Ensure strategy setup is in place
	if err := strat.EnsureSetup(); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
	}

	entireSessionID := currentSessionIDWithFallback(input.SessionID)

	// Get agent type from the currently executing hook agent (authoritative source)
	var agentType agent.AgentType
	if hookAgent, agentErr := GetCurrentHookAgent(); agentErr == nil {
		agentType = hookAgent.Type()
	}

	// Build task checkpoint context - strategy handles metadata creation
	// Note: Incremental checkpoints are now created during task execution via handlePostTodo,
	// so we don't need to collect/cleanup staging area here.
	ctx := strategy.TaskCheckpointContext{
		SessionID:              entireSessionID,
		ToolUseID:              input.ToolUseID,
		AgentID:                input.AgentID,
		ModifiedFiles:          relModifiedFiles,
		NewFiles:               relNewFiles,
		DeletedFiles:           nil, // TODO: compute deleted files
		TranscriptPath:         input.TranscriptPath,
		SubagentTranscriptPath: subagentTranscriptPath,
		CheckpointUUID:         checkpointUUID,
		AuthorName:             author.Name,
		AuthorEmail:            author.Email,
		SubagentType:           subagentType,
		TaskDescription:        taskDescription,
		AgentType:              agentType,
	}

	// Call strategy to save task checkpoint - strategy handles all metadata creation
	if err := strat.SaveTaskCheckpoint(ctx); err != nil {
		return fmt.Errorf("failed to save task checkpoint: %w", err)
	}

	// Cleanup pre-task state (ignore error - cleanup is best-effort)
	_ = CleanupPreTaskState(input.ToolUseID) //nolint:errcheck // best-effort cleanup

	return nil
}

// handleSessionStart handles the SessionStart hook for Claude Code.
// It reads session info from stdin and sets it as the current session.
func handleSessionStart() error {
	// Get the agent for session ID transformation
	ag, err := GetCurrentHookAgent()
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Parse hook input using agent interface
	input, err := ag.ParseHookInput(agent.HookSessionStart, os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to parse hook input: %w", err)
	}

	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
	logging.Info(logCtx, "session-start",
		slog.String("hook", "session-start"),
		slog.String("hook_type", "agent"),
		slog.String("model_session_id", input.SessionID),
		slog.String("transcript_path", input.SessionRef),
	)

	if input.SessionID == "" {
		return errors.New("no session_id in input")
	}

	// Get or create stable session ID (reuses existing if session resumed across days)
	entireSessionID := session.GetOrCreateEntireSessionID(input.SessionID)

	// Write session ID to current_session file
	if err := paths.WriteCurrentSession(entireSessionID); err != nil {
		return fmt.Errorf("failed to set current session: %w", err)
	}

	fmt.Printf("Current session set to: %s\n", entireSessionID)
	return nil
}

// hookResponse represents a JSON response for Claude Code hooks.
// Used to control whether Claude continues processing the prompt.
type hookResponse struct {
	Continue   bool   `json:"continue"`
	StopReason string `json:"stopReason,omitempty"`
}

// outputHookResponse outputs a JSON response to stdout for Claude Code hooks.
// When continueExec is false, Claude will block the current operation and show the reason to the user.
func outputHookResponse(continueExec bool, reason string) error {
	resp := hookResponse{
		Continue:   continueExec,
		StopReason: reason,
	}
	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
		return fmt.Errorf("failed to encode hook response: %w", err)
	}
	return nil
}

// Package strategy provides an interface for different git strategies
// that can be used to save and manage Claude Code session changes.
package strategy

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
)

// ErrNoMetadata is returned when a commit does not have an Entire metadata trailer.
var ErrNoMetadata = errors.New("commit has no entire metadata")

// ErrNoSession is returned when no session info is available.
var ErrNoSession = errors.New("no session info available")

// ErrNotTaskCheckpoint is returned when a rewind point is not a task checkpoint.
var ErrNotTaskCheckpoint = errors.New("not a task checkpoint")

// ErrNotImplemented is returned when a feature is not yet implemented.
var ErrNotImplemented = errors.New("not implemented")

// ShadowBranchConflictError is returned when a shadow branch already exists
// with activity from a different session or worktree.
type ShadowBranchConflictError struct {
	Branch           string    // The shadow branch name (e.g., "entire/abc1234")
	ExistingSession  string    // Session ID of the existing session
	ExistingWorktree string    // Worktree path of the existing session
	LastActivity     time.Time // When the existing session was last active
	CurrentSession   string    // Session ID of the current session attempting to start
	CurrentWorktree  string    // Worktree path of the current session
}

func (e *ShadowBranchConflictError) Error() string {
	return "shadow branch conflict: existing session from different worktree"
}

// SessionIDConflictError is returned when trying to start a new session
// but the shadow branch already has commits from a different session ID.
// This prevents orphaning existing session work.
type SessionIDConflictError struct {
	ExistingSession string // Session ID found in the shadow branch
	NewSession      string // Session ID being initialized
	ShadowBranch    string // The shadow branch name (e.g., "entire/abc1234")
}

func (e *SessionIDConflictError) Error() string {
	return "session ID conflict: shadow branch has commits from a different session"
}

// ExtractToolUseIDFromTaskMetadataDir extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
// Returns empty string if not a task metadata directory.
func ExtractToolUseIDFromTaskMetadataDir(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// SessionInfo contains information about the current session state.
// This is used to generate trailers for linking commits to their AI session.
type SessionInfo struct {
	// SessionID is the session identifier extracted from the latest commit's metadata
	SessionID string

	// Reference is a strategy-specific reference string.
	// For manual-commit strategy: "entire/abc1234" (the shadow branch name)
	// Empty for commit strategy (metadata is in the same commit).
	Reference string

	// CommitHash is the full SHA of the commit containing the session metadata.
	// Empty for commit strategy.
	CommitHash string
}

// RewindPoint represents a point to which the user can rewind.
// This abstraction allows different strategies to use different
// identifiers (commit hashes, branch names, stash refs, etc.)
type RewindPoint struct {
	// ID is the unique identifier for this rewind point
	// (commit hash, branch name, stash ref, etc.)
	ID string

	// Message is the human-readable description/summary
	Message string

	// MetadataDir is the path to the metadata directory
	MetadataDir string

	// Date is when this rewind point was created
	Date time.Time

	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
	IsTaskCheckpoint bool

	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
	ToolUseID string

	// IsLogsOnly indicates this is a commit with session logs but no shadow branch state.
	// The logs can be restored from entire/sessions, but file state requires git checkout.
	IsLogsOnly bool

	// CheckpointID is the stable 12-hex-char identifier for logs-only points.
	// Used to retrieve logs from entire/sessions/<id[:2]>/<id[2:]>/full.jsonl
	// Empty for shadow branch checkpoints (uncommitted).
	CheckpointID id.CheckpointID

	// Agent is the human-readable name of the agent that created this checkpoint
	// (e.g., "Claude Code", "Cursor")
	Agent agent.AgentType

	// SessionID is the session identifier for this checkpoint.
	// Used to distinguish checkpoints from different concurrent sessions.
	SessionID string

	// SessionPrompt is the initial prompt that started this session.
	// Used to help users identify which session a checkpoint belongs to.
	SessionPrompt string

	// SessionCount is the number of sessions in this checkpoint (1 for single-session).
	// Only populated for logs-only points with multi-session checkpoints.
	SessionCount int

	// SessionIDs contains all session IDs when this is a multi-session checkpoint.
	// The last entry is the most recent session (same as SessionID).
	// Only populated for logs-only points with multi-session checkpoints.
	SessionIDs []string

	// SessionPrompts contains the first prompt for each session (parallel to SessionIDs).
	// Used to display context when showing resume commands for multi-session checkpoints.
	SessionPrompts []string
}

// RewindPreview describes what will happen when rewinding to a checkpoint.
// Used to warn users about files that will be modified or deleted.
type RewindPreview struct {
	// FilesToRestore are files from the checkpoint that will be written/restored.
	FilesToRestore []string

	// FilesToDelete are untracked files that will be removed.
	// These are files created after the checkpoint that aren't in the checkpoint tree
	// and weren't present at session start.
	FilesToDelete []string

	FilesToDelete []string

	// TrackedChanges are tracked files with uncommitted changes that will be reverted.
	// These come from the existing CanRewind() warning.
	TrackedChanges []string
}

// SaveContext contains all information needed for saving changes.
// All file paths should be pre-filtered and normalized by the CLI layer.
type SaveContext struct {
	// SessionID is the Claude Code session identifier
	SessionID string

	// ModifiedFiles is the list of files modified during the session
	// (extracted from the transcript, already filtered and relative)
	ModifiedFiles []string

	// NewFiles is the list of new files created during the session
	// (pre-computed by CLI from pre-prompt state comparison)
	NewFiles []string

	// DeletedFiles is the list of files deleted during the session
	// (tracked files that no longer exist)
	DeletedFiles []string

	// MetadataDir is the path to the session metadata directory
	MetadataDir string

	// MetadataDirAbs is the absolute path to the session metadata directory
	MetadataDirAbs string

	// CommitMessage is the generated commit message
	CommitMessage string

	// TranscriptPath is the path to the transcript file
	TranscriptPath string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// AgentType is the human-readable agent name (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// Transcript position at checkpoint start - tracks what was added during this checkpoint
	TranscriptIdentifierAtStart string // Last identifier when checkpoint started (UUID for Claude, message ID for Gemini)
	TranscriptLinesAtStart      int    // Line count when checkpoint started

	// TokenUsage contains the token usage for this checkpoint
	TokenUsage *agent.TokenUsage
}

// TaskCheckpointContext contains all information needed for saving a task checkpoint.
// This is called by the PostToolUse[Task] hook when a subagent completes.
// The strategy is responsible for creating metadata structures and storing them
// according to its storage approach.
type TaskCheckpointContext struct {
	// SessionID is the Claude Code session identifier
	SessionID string

	// ToolUseID is the unique identifier for this Task tool invocation
	ToolUseID string

	// AgentID is the subagent identifier (from tool_response.agentId)
	AgentID string

	// ModifiedFiles is the list of files modified by the subagent
	// (extracted from the subagent's transcript)
	ModifiedFiles []string

	// NewFiles is the list of new files created by the subagent
	// (computed from pre-task state comparison)
	NewFiles []string

	// DeletedFiles is the list of files deleted by the subagent
	DeletedFiles []string

	// TranscriptPath is the path to the main session transcript
	TranscriptPath string

	// SubagentTranscriptPath is the path to the subagent's transcript (if available)
	SubagentTranscriptPath string

	// CheckpointUUID is the UUID for transcript truncation when rewinding
	CheckpointUUID string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsIncremental indicates this is an incremental checkpoint during task execution,
	// not a final task completion checkpoint. When true:
	// - Writes to checkpoints/NNN-{tool-use-id}.json instead of checkpoint.json
	// - Skips transcript handling
	// - Uses incremental commit message
	IsIncremental bool

	// IncrementalSequence is the checkpoint sequence number (1, 2, 3, ...)
	// Only used when IsIncremental is true
	IncrementalSequence int

	// IncrementalType is the tool that triggered this checkpoint ("TodoWrite", "Edit", etc.)
	// Only used when IsIncremental is true
	IncrementalType string

	// IncrementalData is the tool_input payload for this checkpoint
	// Only used when IsIncremental is true
	IncrementalData json.RawMessage

	// SubagentType is the type of subagent (e.g., "dev", "reviewer")
	// Extracted from tool_input.subagent_type in Task tool
	// Used for descriptive commit messages
	SubagentType string

	// TaskDescription is the task description provided to the subagent
	// Extracted from tool_input.description in Task tool
	// Used for descriptive commit messages
	TaskDescription string

	// TodoContent is the content of the in-progress todo item
	// Extracted from tool_input.todos where status == "in_progress"
	// Used for descriptive incremental checkpoint messages
	TodoContent string

	// AgentType is the human-readable agent name (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType
}

// TaskCheckpoint contains the checkpoint information written to checkpoint.json
type TaskCheckpoint struct {
	SessionID      string `json:"session_id"`
	ToolUseID      string `json:"tool_use_id"`
	CheckpointUUID string `json:"checkpoint_uuid"`
	AgentID        string `json:"agent_id,omitempty"`
}

// SubagentCheckpoint represents an intermediate checkpoint created during subagent execution.
// These are created by PostToolUse hooks for tools like TodoWrite, Edit, Write.
type SubagentCheckpoint struct {
	Type      string          `json:"type"`        // Tool name: "TodoWrite", "Edit", "Write"
	ToolUseID string          `json:"tool_use_id"` // The tool use ID that created this checkpoint
	Timestamp time.Time       `json:"timestamp"`   // When the checkpoint was created
	Data      json.RawMessage `json:"data"`        // Type-specific payload (tool_input)
}

// TaskMetadataDir returns the path to a task's metadata directory

// Package sessionid provides session ID formatting and transformation functions.
// This package has minimal dependencies to avoid import cycles.
package sessionid

import (
	"time"
)

// EntireSessionID generates the full Entire session ID from an agent session UUID.
// The format is: YYYY-MM-DD-<agent-session-uuid>
func EntireSessionID(agentSessionUUID string) string {
	return time.Now().Format("2006-01-02") + "-" + agentSessionUUID
}

// ModelSessionID extracts the agent session UUID from an Entire session ID.
// The Entire session ID format is: YYYY-MM-DD-<agent-session-uuid>
// Returns the original string if it doesn't match the expected format.
func ModelSessionID(entireSessionID string) string {
	// Expected format: YYYY-MM-DD-<agent-uuid> (11 chars prefix: "2026-01-23-")
	if len(entireSessionID) > 11 && entireSessionID[4] == '-' && entireSessionID[7] == '-' && entireSessionID[10] == '-' {
		return entireSessionID[11:]
	}
	// Return as-is if not in expected format (backwards compatibility)
	return entireSessionID
}

package sessionid

import (
	"strings"
	"testing"
	"time"
)

func TestModelSessionID(t *testing.T) {
	tests := []struct {
		name            string
		entireSessionID string
		expectedModelID string
	}{
		// Valid format - extracts UUID
		{
			name:            "valid format with full uuid",
			entireSessionID: "2026-01-23-f736da47-b2ca-4f86-bb32-a1bbe582e464",
			expectedModelID: "f736da47-b2ca-4f86-bb32-a1bbe582e464",
		},
		{
			name:            "valid format with short uuid",
			entireSessionID: "2026-01-23-abc123",
			expectedModelID: "abc123",
		},
		{
			name:            "valid format different year",
			entireSessionID: "2025-12-31-test-session-uuid",
			expectedModelID: "test-session-uuid",
		},
		{
			name:            "valid format single digit day",
			entireSessionID: "2026-01-05-uuid-here",
			expectedModelID: "uuid-here",
		},
		{
			name:            "valid format with complex uuid",
			entireSessionID: "2026-11-30-a1b2c3d4_e5f6_7890",
			expectedModelID: "a1b2c3d4_e5f6_7890",
		},
		// Invalid format - returns as-is (backwards compatibility)
		{
			name:            "no date prefix - plain uuid",
			entireSessionID: "f736da47-b2ca-4f86-bb32-a1bbe582e464",
			expectedModelID: "f736da47-b2ca-4f86-bb32-a1bbe582e464",
		},
		{
			name:            "malformed date - missing second hyphen",
			entireSessionID: "2026-0123-uuid",
			expectedModelID: "2026-0123-uuid",
		},
		{
			name:            "malformed date - missing third hyphen",
			entireSessionID: "2026-01-23uuid",
			expectedModelID: "2026-01-23uuid",
		},
		{
			name:            "too short - only date prefix",
			entireSessionID: "2026-01-23-",
			expectedModelID: "2026-01-23-",
		},
		{
			name:            "too short - less than 11 chars",
			entireSessionID: "2026-01-23",
			expectedModelID: "2026-01-23",
		},
		{
			name:            "empty string",
			entireSessionID: "",
			expectedModelID: "",
		},
		{
			name:            "wrong hyphen positions",
			entireSessionID: "20260-1-23-uuid",
			expectedModelID: "20260-1-23-uuid",
		},
		{
			name:            "date with slashes instead of hyphens",
			entireSessionID: "2026/01/23-uuid",
			expectedModelID: "2026/01/23-uuid",
		},
		{
			name:            "valid format edge case - exactly 11 char prefix",
			entireSessionID: "2026-01-23-x",
			expectedModelID: "x",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := ModelSessionID(tt.entireSessionID)
			if result != tt.expectedModelID {
				t.Errorf("ModelSessionID(%q) = %q, want %q", tt.entireSessionID, result, tt.expectedModelID)
			}
		})
	}
}

func TestEntireSessionID(t *testing.T) {
	tests := []struct {
		name             string
		agentSessionUUID string
	}{
		{name: "full uuid", agentSessionUUID: "f736da47-b2ca-4f86-bb32-a1bbe582e464"},
		{name: "short id", agentSessionUUID: "abc123"},
		{name: "empty uuid", agentSessionUUID: ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := EntireSessionID(tt.agentSessionUUID)

			// Verify format: YYYY-MM-DD-<uuid>
			expectedPrefix := time.Now().Format("2006-01-02") + "-"
			if !strings.HasPrefix(result, expectedPrefix) {
				t.Errorf("EntireSessionID(%q) = %q, expected to start with %q", tt.agentSessionUUID, result, expectedPrefix)
			}

			// Verify UUID is appended correctly
			expectedSuffix := tt.agentSessionUUID
			if !strings.HasSuffix(result, expectedSuffix) {
				t.Errorf("EntireSessionID(%q) = %q, expected to end with %q", tt.agentSessionUUID, result, expectedSuffix)
			}

			// Verify complete format
			expected := expectedPrefix + tt.agentSessionUUID
			if result != expected {
				t.Errorf("EntireSessionID(%q) = %q, want %q", tt.agentSessionUUID, result, expected)
			}
		})
	}
}

// TestRoundTrip verifies that EntireSessionID and ModelSessionID are inverses
func TestRoundTrip(t *testing.T) {
	tests := []struct {
		name string
		uuid string
	}{
		{name: "full uuid", uuid: "f736da47-b2ca-4f86-bb32-a1bbe582e464"},
		{name: "short id", uuid: "abc123"},
		{name: "uuid with underscores", uuid: "test_session_uuid_123"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// UUID -> Entire session ID -> UUID
			entireID := EntireSessionID(tt.uuid)
			extractedUUID := ModelSessionID(entireID)

			if extractedUUID != tt.uuid {
				t.Errorf("Round trip failed: %q -> EntireSessionID -> %q -> ModelSessionID -> %q",
					tt.uuid, entireID, extractedUUID)
			}
		})
	}
}

// Package session provides domain types and interfaces for managing AI coding sessions.
//
// A Session represents a unit of work with an AI agent (Claude Code, Cursor, etc.).
// Sessions can be nested - when a subagent runs, it creates a sub-session within
// the parent session.
//
// This package provides two levels of abstraction:
//
//  1. Sessions interface - High-level CRUD operations for full session objects,
//     combining session state with checkpoint data. This is the primary interface
//     for commands and the UI layer.
//
//  2. StateStore - Low-level primitive for managing session state files in
//     .git/entire-sessions/. This tracks active session state (base commit,
//     checkpoint count, etc.) but doesn't handle checkpoint content. Strategies
//     use this directly for performance-critical state management.
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package session

import (
	"context"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint"
)

// Session represents a unit of work with an AI coding agent.
// Sessions can be nested when subagents are used.
type Session struct {
	// ID is the unique session identifier
	ID string

	// FirstPrompt is the raw first user prompt (immutable)
	FirstPrompt string

	// Description is a human-readable summary (derived or editable)
	Description string

	// StartTime is when the session was started
	StartTime time.Time

	// AgentType identifies the AI agent (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// AgentSessionID is the agent's internal session identifier
	AgentSessionID string

	// Checkpoints contains save points within this session
	Checkpoints []checkpoint.Checkpoint

	// SubSessions contains nested sessions from subagent work
	SubSessions []Session

	// ParentID is the parent session ID (empty for top-level sessions)
	ParentID string

	// ToolUseID is the tool invocation that spawned this sub-session
	// (empty for top-level sessions)
	ToolUseID string
}

// IsSubSession returns true if this session is a sub-session (has a parent).
func (s *Session) IsSubSession() bool {
	return s.ParentID != ""
}

// Sessions provides operations for managing sessions.
type Sessions interface {
	// Create creates a new session with the given options.
	Create(ctx context.Context, opts CreateSessionOptions) (*Session, error)

	// Get retrieves a session by ID.
	Get(ctx context.Context, sessionID string) (*Session, error)

	// List returns all top-level sessions (excludes sub-sessions).
	List(ctx context.Context) ([]Session, error)
}

// CreateSessionOptions contains parameters for creating a new session.
type CreateSessionOptions struct {
	// FirstPrompt is the initial user prompt
	FirstPrompt string

	// AgentType identifies the AI agent (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// AgentSessionID is the agent's internal session identifier
	AgentSessionID string

	// ParentID is the parent session ID for sub-sessions (empty for top-level)
	ParentID string

	// ToolUseID is the tool invocation that spawned this sub-session
	// (empty for top-level sessions)
	ToolUseID string
}

