   347→		return 0, nil
   348→	}
   349→
   350→	file, err := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
   351→	if err != nil {
   352→		if os.IsNotExist(err) {
   353→			return 0, nil
   354→		}
   355→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
   356→	}
