   376→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
   377→// For Claude Code (JSONL format), offset is the starting line number.
   378→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
   379→// Returns:
   380→//   - files: list of file paths modified by Claude (from Write/Edit tools)
   381→//   - currentPosition: total number of lines in the file
   382→//   - error: any error encountered during reading
   383→func (c *ClaudeCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
   384→	if path == "" {
   385→		return nil, 0, nil
   386→	}
   387→
   388→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
   389→	if openErr != nil {
   390→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
   391→	}
   392→	defer file.Close()
   393→
   394→	reader := bufio.NewReader(file)
   395→	var lines []TranscriptLine
   396→	lineNum := 0
   397→
   398→	for {
   399→		lineData, readErr := reader.ReadBytes('\n')
   400→		if readErr != nil && readErr != io.EOF {
   401→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
   402→		}
   403→
   404→		if len(lineData) > 0 {
   405→			lineNum++
   406→			if lineNum > startOffset {
   407→				var line TranscriptLine
   408→				if parseErr := json.Unmarshal(lineData, &line); parseErr == nil {
   409→					lines = append(lines, line)
   410→				}
   411→				// Skip malformed lines silently
   412→			}
   413→		}
   414→
   415→		if readErr == io.EOF {
   416→			break
   417→		}
   418→	}
   419→
   420→	return ExtractModifiedFiles(lines), lineNum, nil
   421→}
   422→
   423→// TranscriptChunker interface implementation
   424→
   425→// ChunkTranscript splits a JSONL transcript at line boundaries.
   426→// Claude Code uses JSONL format (one JSON object per line), so chunking
   427→// is done at newline boundaries to preserve message integrity.
   428→func (c *ClaudeCodeAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
   429→	chunks, err := agent.ChunkJSONL(content, maxSize)
   430→	if err != nil {
   431→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
   432→	}
   433→	return chunks, nil
   434→}
   435→
   436→// ReassembleTranscript concatenates JSONL chunks with newlines.
   437→//
   438→//nolint:unparam // error return is required by interface, kept for consistency
   439→func (c *ClaudeCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
   440→	return agent.ReassembleJSONL(chunks), nil
   441→}
