			t.Error("FindCheckpointUUID() found = false, want true")
		}
		if uuid != "u1" {
			t.Errorf("FindCheckpointUUID() uuid = %q, want %q", uuid, "u1")
		}
	})

	t.Run("TransformSessionID is identity function", func(t *testing.T) {
